dependencies.target:
nodes
    .filter(node => node.id !== edge.from && node.id !== edge.to)
    .map(node => {
      const position = positions[String(node.id)];
      return position ? {
        left: position.x - 24,
        right: position.x + NODE_WIDTH + 24,
        top: position.y - 24,
        bottom: position.y + NODE_HEIGHT + 24
      } : null;
    })
    .filter
